import{_ as p,a0 as u,w as d,s as e,ao as r,I as n,x as t,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"為什麼（大多數）高級語言運行效率較慢 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼（大多數）高級語言運行效率較慢 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼（大多數）高級語言運行效率較慢 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼（大多數）高級語言運行效率較慢 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20150413 Why  most High Level Languages are Slow","title":"為什麼（大多數）高級語言運行效率較慢","tag":"201703","desc":""},"relativePath":"201703/20150413 Why  most High Level Languages are Slow.md","filePath":"[post].md"}'),m={name:"201703/20150413 Why  most High Level Languages are Slow.md"};function C(f,l,a,g,w,T){const s=u("Link");return d(),e("div",null,[l[50]||(l[50]=r('<h1 id="為什麼-大多數-高級語言運行效率較慢" tabindex="-1">為什麼（大多數）高級語言運行效率較慢 <a class="header-anchor" href="#為什麼-大多數-高級語言運行效率較慢" aria-label="Permalink to “為什麼（大多數）高級語言運行效率較慢”">​</a></h1><p>在近一兩個月中，我多次的和線上線下的朋友討論了這個話題，所以我乾脆直接把它寫在Blog中，以便以後查閲。</p><p>大部分高級語言運行效率較慢的原因通常有兩點：</p><ol><li>沒有很好的利用緩存；</li><li>垃圾回收機制性能消耗高。</li></ol><p>但事實上，這兩個原因可以歸因於：高級語言強烈地鼓勵編程人員分配很多的內存。</p><p>首先，下文內容主要討論客户端應用。如果你的程序有 99.9% 的時間都在等待網絡 I/O，那麼這很可能不是拖慢語言運行效率的原因——優先考慮的問題當然是優化網絡。在本文中，我們主要討論程序在本地執行的速度。</p><p>我將選用 C# 語言作為本文的參考語言，其原因有二：首先它是我常用的高級語言；其次如果我使用 Java 語言，許多使用 C# 的朋友會告訴我 C# 不會有這些問題，因為它有值類型（但這是錯誤的）。</p><p>接下來我將會討論，出於編程習慣編寫的代碼、使用普遍編程方法（with the grain）的代碼或使用庫或教程中提到的常用代碼來編寫程序時會發生什麼。我對那些使用難搞的辦法來解決語言自身毛病以“證明”語言沒毛病這事沒興趣，當然你可以和語言抗爭來避免它的毛病，但這並不能説明語言本身是沒有問題的。</p><h3 id="回顧緩存消耗問題" tabindex="-1">回顧緩存消耗問題 <a class="header-anchor" href="#回顧緩存消耗問題" aria-label="Permalink to “回顧緩存消耗問題”">​</a></h3>',9)),n("p",null,[l[1]||(l[1]=t("首先我們先來回顧一下合理使用緩存的重要性。下圖是基於在 Haswell 架構下內存延遲對 CPU 影響的 ",-1)),o(s,{href:"http://www.7-cpu.com/cpu/Haswell.html"},{default:i(()=>[...l[0]||(l[0]=[t("數據",-1)])]),_:1}),l[2]||(l[2]=t("：",-1))]),l[51]||(l[51]=n("p",null,[n("img",{src:"https://www.sebastiansylvan.com/img/041315_0638_whymosthigh1.png",alt:""})],-1)),l[52]||(l[52]=n("p",null,"針對這款 CPU 讀取內存的延遲，CPU 需要消耗近 230 個運算週期從內存讀取數據，同時需要消耗 4 個運算週期來讀取 L1 緩衝區。因此錯誤的去使用緩存可導致運行速度拖慢近 50 倍。還好這並不是最糟糕的——在現代 CPU 中它們能同時地做多種操作，所以當你加載 L1 緩衝區內容的同時這個內容已經進入到了寄存器，因此數據從 L1 緩衝區加載這個過程的性能消耗就被部分或完整的掩蓋了起來。",-1)),l[53]||(l[53]=n("p",null,"撇開選擇合理的算法不談，不誇張地講，在性能優化中你要考慮的最主要因素其實是緩存未命中。當你能夠有效的訪問一個數據時候，你才需要考慮優化你的每個具體的操作。與緩存未命中的問題相比，那些次要的低效問題對運行速度並沒有什麼過多的影響。",-1)),l[54]||(l[54]=n("p",null,"這對於編程語言的設計者來説是一個好消息！你都_不必_去編寫一個最高效的編譯器，你可以完全擺脱一些額外的開銷（比如：數組邊界檢查），你只需要專注怎麼設計語言能高效地編寫代碼來訪問數據，而不用擔心與 C 語言代碼比較運行速度。",-1)),l[55]||(l[55]=n("h3",{id:"為什麼-c-存在緩存未命中問題",tabindex:"-1"},[t("為什麼 C# 存在緩存未命中問題 "),n("a",{class:"header-anchor",href:"#為什麼-c-存在緩存未命中問題","aria-label":"Permalink to “為什麼 C# 存在緩存未命中問題”"},"​")],-1)),l[56]||(l[56]=n("p",null,"坦率地講 C# 在設計時就沒打算在現代緩存中實現高效運行。我又一次提到程序語言設計的侷限性以及其帶給程序員無法編寫高效的代碼的“壓力”。大部分的理論上的解決方法其實都非常的不便，這裏我説的是那些編程語言“希望”你這樣編寫的慣用寫法。",-1)),l[57]||(l[57]=n("p",null,"C# 最基本的問題是對基礎值類型（value-base）低下的支持性。其大部分的數據結構都是“內置”在語言內定義的（例如：棧，或其他內置對象）。但這些具有幫助性的內置結構體有一些大問題，以至於更像是創可貼而不是解決方案。",-1)),n("ul",null,[l[18]||(l[18]=n("li",null,[n("p",null,"你得把自己定義的結構體類型在最先聲明——這意味着你如果需要用到這個類型作為堆分配，那麼所有的結構體都會被堆分配。你也可以使用一些類包裝器來打包你的結構體和其中的成員變量，但這十分的痛苦。如果類和結構體可以相同的方式聲明，並且可根據具體情況來使用，這將是更好的。當數據可以作為值地存儲在自定義的棧中，當這個數據需要被堆分配時你就可以將其定義為一個對象，比如 C++ 就是這樣工作的。因為只有少數的內容需要被堆分配，所以我們不鼓勵所有的內容都被定義為對象類型。")],-1)),l[19]||(l[19]=n("li",null,[n("p",null,[n("em",null,"引用"),t(" 值被苛刻的限制。你可以將一個引用值傳給函數，但只能這樣。你不能直接引用 "),n("code",null,"List<int>"),t(" 中的元素，你必須先把所有的引用和索引全部存儲下來。你不能直接取得指向棧、對象中的變量（或其他變量）的指針。你只能把它們複製一份，除了將它們傳給一個函數（使用引用的方式）。當然這也是可以理解的。如果類型安全是一個先驅條件，靈活的引用變量和保證類型安全這兩項要同時支持太難了（雖然不是不可能）。這些限制背後的理念並不能改變限制存在的事實。")])],-1)),n("li",null,[n("p",null,[o(s,{href:"https://msdn.microsoft.com/en-us/library/vstudio/zycewsya(v=vs.100).aspx"},{default:i(()=>[...l[3]||(l[3]=[t("固定大小的緩衝區",-1)])]),_:1}),l[4]||(l[4]=t(" 不支持自定義類型，而且還必須使用 ",-1)),l[5]||(l[5]=n("code",null,"unsafe",-1)),l[6]||(l[6]=t(" 關鍵字。",-1))])]),n("li",null,[n("p",null,[l[8]||(l[8]=t("有限的“數組切片”功能。雖然有提供 ",-1)),l[9]||(l[9]=n("code",null,"ArraySegment",-1)),l[10]||(l[10]=t(" 類，但並沒有人會使用它，這意味着如果只需要傳遞數組的一部分，你必須去創建一個 ",-1)),l[11]||(l[11]=n("code",null,"IEnumerable",-1)),l[12]||(l[12]=t(" 對象，也就意味着要分配大小（包裝）。就算接口接受 ",-1)),l[13]||(l[13]=n("code",null,"ArraySegment",-1)),l[14]||(l[14]=t(" 對象作為參數，也是不夠的——你只能用普通數組，而不能用 ",-1)),l[15]||(l[15]=n("code",null,"List<T>",-1)),l[16]||(l[16]=t("，也不能用 ",-1)),o(s,{href:"https://msdn.microsoft.com/en-us/library/vstudio/cx9s2sy4(v=vs.100).aspx"},{default:i(()=>[...l[7]||(l[7]=[t("棧數組",-1)])]),_:1}),l[17]||(l[17]=t(" 等等。",-1))])])]),n("p",null,[l[21]||(l[21]=t("最重要的是，除了非常簡單的情況之外，C# 非常慣用堆分配。如果所有的數據都被堆分配，這意味着被訪問時會造成緩存未命中（從你無法決定對象是如何在堆中存儲開始）。所以當 C++ 程序面臨着如何有效的組織數據在緩存中的存儲這個挑戰時，C# 則鼓勵程序員去將數據分開地存放在一個個堆分配空間中。這就意味着程序員無法控制數據存儲方式了，也開始產生不必要的緩存未命中問題，而導致性能急速的下降。",-1)),o(s,{href:"https://msdn.microsoft.com/en-us/vstudio/dotnetnative.aspx"},{default:i(()=>[...l[20]||(l[20]=[t("C# 已經支持原生編譯",-1)])]),_:1}),l[22]||(l[22]=t(" 也不會提升太多性能——畢竟在內存不足的情況下，提高代碼質量本就杯水車薪。",-1))]),l[58]||(l[58]=n("p",null,"再加上存儲是有開銷的。在 64 位的機器上每個地址值佔 8 位內存，而每次分配都會有存儲元數據而產生的開銷。與存儲着少量大數據（以固定偏移的方式存儲在其中）的堆相比，存儲着大量小數據的堆（並且其中的數據到處都被引用）會產生更多的內存開銷。儘管你可能不怎麼關心內存怎麼用，但事實上就是那些頭部內容和地址信息導致堆變得臃腫，也就是在浪費緩存了，所以也造成了更多的緩存未命中，降低了代碼性能。",-1)),l[59]||(l[59]=n("p",null,[t("當然有些時候也是有辦法的，比如你可以使用一個很大的 "),n("code",null,"List<T>"),t(" 來構造數據池以存儲分配你需要的數據和自己的結構體。這樣你就可以方便的遍歷或者批量更新你的數據池中的數據了。但這也會很混亂，因為無論你在哪要引用什麼對象都要先能引用這個池，然後每次引用都需要做數組索引。從上文可以得出，在 C# 中做類似這樣的處理的痛感比在 C++ 中做來的更痛，因為 C# 在設計時就是這樣。此外，通過這種方式來訪問池中的單個對象比直接將這個對象分配到內存來訪問更加的昂貴——前者你得先訪問池（這是個類）的地址，這意味着可能產生 "),n("em",null,"2"),t(" 次緩存未命中。你還可以通過複製 "),n("code",null,"List<T>"),t(" 的結構形式來避免更多的緩存未命中問題，但這就更難搞了。我就寫過很多類似的代碼，自然這樣的代碼只會水平很低而且容易出錯。")],-1)),n("p",null,[l[24]||(l[24]=t("最後，我想説我指出的問題不僅是那些“熱門”的代碼。慣用手段編寫的 C# 代碼傾向於幾乎所有地方都用類和引用。意思就是在你的代碼中會頻率均勻地隨機出現數百次的運算週期損耗，使得操作的損耗似乎降低了。這雖然也可以被找出來，但你優化了這問題後，這還是一個 ",-1)),o(s,{href:"http://c2.com/cgi/wiki?UniformlySlowCode"},{default:i(()=>[...l[23]||(l[23]=[t("均勻變慢",-1)])]),_:1}),l[25]||(l[25]=t(" 的程序。",-1))]),l[60]||(l[60]=n("h3",{id:"垃圾回收",tabindex:"-1"},[t("垃圾回收 "),n("a",{class:"header-anchor",href:"#垃圾回收","aria-label":"Permalink to “垃圾回收”"},"​")],-1)),l[61]||(l[61]=n("p",null,"在讀下文之前我會假設你已經知道為什麼在許多用例中垃圾回收是影響性能問題的重要原因。播放動畫時總是隨機的暫停通常都是大家都不能接受的吧。我會繼續解釋為什麼設計語言時還加劇了這個問題。",-1)),l[62]||(l[62]=n("p",null,"因為 C# 在處理變量上的一些侷限性，它強烈不建議你去使用大內存塊分配來存儲很多里面是內置對象的變量（可能存在棧中），這就使得你必須使用很多分配在堆中的小型類對象。説白了就是內存分配越多會導致花在垃圾回收上的時間就越多。",-1)),l[63]||(l[63]=n("p",null,"有些測評説 C# 或者 Java 是怎麼在一些特定的例子中打敗 C++ 的，其實是因為內存分配器都基於一種吞吐還算不錯的垃圾回收機制（廉價的分配，允許統一的釋放分配）。然而，這些測試場景都太特殊了。想要使 C# 的程序的內存分配率變得和那些非常普通的 C++ 程序都能達到的一樣就必須要耗費更大的精力來編寫它，所以這種比較就像是拿一個高度優化的管理程序和一個最簡單原生的程序相比較一樣。當你花同樣的精力來寫一個 C++ 程序時，肯定比你用 C# 來寫性能好的多。",-1)),l[64]||(l[64]=n("p",null,[t("我還是相信你可以寫出一套適用於高性能低延遲的應用的垃圾回收機制的（比如維護一個增量的垃圾回收，每次消耗固定的時間來做回收），但這還是不夠的，大部分的高級語言在設計時就沒考慮程序啓動時就會產生大量的垃圾，這將會是最大的問題。當你就像寫 C 一樣習慣的去少去在 C# 分配內存，垃圾回收在高性能應用中可能就不會暴露出很多的問題了。而就算你 "),n("em",null,"真的"),t(" 去實現了一個增量垃圾回收機制，這意味着你還可能需要為其做一個寫屏障——這就相當於又消耗了一些性能了。")],-1)),n("p",null,[l[27]||(l[27]=t("看看 ",-1)),l[28]||(l[28]=n("code",null,".Net",-1)),l[29]||(l[29]=t(" 庫裏那些基本類，內存分配幾乎無處不在！我數了下，在 ",-1)),o(s,{href:"https://github.com/dotnet/corefx"},{default:i(()=>[...l[26]||(l[26]=[t(".Net 核心框架",-1)])]),_:1}),l[30]||(l[30]=t(" 中公共類比結構體的數量多出 19 倍之多，為了使用它們，你就得把這些東西全都弄到內存中去。就算是 ",-1)),l[31]||(l[31]=n("code",null,".Net",-1)),l[32]||(l[32]=t(" 框架的創造者們也無法抵抗設計語言時的警告啊！我都不知道怎麼去統計了，使用基礎類庫時，你會很快意識到這不僅僅是值或對象的選擇問題了，就算如此也還是 ",-1)),l[33]||(l[33]=n("em",null,"伴隨",-1)),l[34]||(l[34]=t(" 着超級多的內存分配。這一切都讓你覺得分配內存好像很容易一樣，其實怎麼可能呢，沒有內存分配你連一個整形值都沒法輸出！不説這個，就算你使用預分配的 ",-1)),l[35]||(l[35]=n("code",null,"StringBuilder",-1)),l[36]||(l[36]=t("，你要是不用標準庫來分配內存，也還不是連個整型都存不住。你要這麼問我那就挺蠢的了。",-1))]),l[65]||(l[65]=r('<p>當然還不僅僅是標準庫，其他的 C# 庫也一樣。就算是 <code>Unity</code>（一個 <em>遊戲引擎</em>，可能能更多的關心平均性能問題）也會有一些全局返回已分配對象（或數組）的接口，或者強制調用時先將其分配內存再使用。舉個例子，在一個 <code>GameObject</code> 中要使用 <code>GetComponents</code> 來調用一個數組，<code>Unity</code> 會強制地分配一個數組以便調用。就此而言，其實有許多的接口可以採用，但他們不選擇，而去走常規路線來直接使用內存分配。寫 <code>Unity</code> 的同胞們寫的一手“好 C#”呀，但就是不那麼高性能罷了。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>如果你在設計一門新的語言，拜託你可以考慮一下我提到的那些性能問題。在你創造出一款“足夠聰明的編譯器”之後這些都不是什麼難題了。當然，沒有垃圾回收器就要求類型安全很難。當然，沒有一個規範的數據表示就創造一個垃圾回收器很難。當然，出現指向隨機值的指針時難以去推出其作用域規則。當然，還有大把大把的問題擺在那裏，然而解決了這些所有的問題，設計出來的語言就會是我們想的那樣嗎？那為什麼這麼多主要的語言都是在那些六十年代就已經被設計出的語言的基礎上迭代的呢？</p><p>儘管你不能修復這些問題，但也許你可以儘可能的靠近？或者可以使用域類型（比如 <code>Rust</code> 語言）去保證其類型安全。或者也許可以考慮直接放棄“類型安全成本”去使用更多的運行時檢查（如果這不會造成更多的緩存未命中的話，這其實沒什麼所謂。其實 C# 也有類似的東西，叫協變式數組，嚴格上講是違背系統數據類型的，會導致一些運行時異常）。</p><p>如果你想在高性能場景中替代 C++，最基本的一點就是要考慮數據的存放佈局和存儲方式。</p><hr><p>作者簡介：</p><p>我叫 Sebastian Sylvan。我來自瑞典，目前居住在西雅圖。我在微軟工作，研究全息透鏡。誠然我的觀點僅代表本人，與微軟公司無關。</p><p>我的Blog以圖像、編程語言、性能等內容為主。聯繫我請點擊我的 Twitter 或 E-mail。</p><hr>',10)),n("p",null,[l[38]||(l[38]=t("via: ",-1)),o(s,{href:"https://www.sebastiansylvan.com/post/why-most-high-level-languages-are-slow"},{default:i(()=>[...l[37]||(l[37]=[t("https://www.sebastiansylvan.com/post/why-most-high-level-languages-are-slow",-1)])]),_:1})]),n("p",null,[l[42]||(l[42]=t("作者：",-1)),o(s,{href:"https://www.sebastiansylvan.com/about/"},{default:i(()=>[...l[39]||(l[39]=[t("Sebastian Sylvan",-1)])]),_:1}),l[43]||(l[43]=t(" 譯者：",-1)),o(s,{href:"https://github.com/kenxx"},{default:i(()=>[...l[40]||(l[40]=[t("kenxx",-1)])]),_:1}),l[44]||(l[44]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...l[41]||(l[41]=[t("wxy",-1)])]),_:1})]),n("p",null,[l[47]||(l[47]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[45]||(l[45]=[t("LCTT",-1)])]),_:1}),l[48]||(l[48]=t(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:i(()=>[...l[46]||(l[46]=[t("Linux中國",-1)])]),_:1}),l[49]||(l[49]=t(" 榮譽推出",-1))])])}const y=p(m,[["render",C]]);export{b as __pageData,y as default};
